protocol.scriptContent:
// GAL-02: STACK -> F.A.S.T. -> STACK plate handoff (STACK in, F.A.S.T. transfer, STACK out).
// Every input is validated and all three parameter objects are built BEFORE the first
// galago call, so a bad input throws with nothing queued. No fallback values live here:
// defaults are the parameter defaults shown in the run form.
// The F.A.S.T. rules below mirror _check_args in tools/fast/server.py (deck 1-6, ids / columns /
// rows >= 1, 1-2 letter rows, volume > 0, tip_reuse fresh or reuse); keep the two in step.
function text(name) {
  var v = params[name];
  return v === undefined || v === null ? "" : String(v).trim();
}
function need(name) {
  var v = text(name);
  if (v === "") { throw new Error("GAL-02: parameter '" + name + "' is required"); }
  return v;
}
function whole(name) {
  var n = Number(need(name));
  if (!isFinite(n) || Math.floor(n) !== n) { throw new Error("GAL-02: parameter '" + name + "' must be a whole number"); }
  if (n < -2147483648 || n > 2147483647) { throw new Error("GAL-02: parameter '" + name + "' must fit a 32-bit integer"); }
  return n;
}
function wholeBetween(name, min, max) {
  var n = whole(name);
  if (n < min || n > max) { throw new Error("GAL-02: parameter '" + name + "' must be a whole number from " + min + " to " + max); }
  return n;
}
function letters(name) {
  var v = need(name);
  var ok = v.length >= 1 && v.length <= 2;
  for (var i = 0; ok && i < v.length; i++) { ok = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".indexOf(v.charAt(i)) >= 0; }
  if (!ok) { throw new Error("GAL-02: parameter '" + name + "' must be one or two letters"); }
  return v;
}
function oneOf(name, allowed) {
  var v = need(name);
  if (allowed.indexOf(v) < 0) { throw new Error("GAL-02: parameter '" + name + "' must be one of " + allowed.join(", ")); }
  return v;
}
function positive(name) {
  var n = Number(need(name));
  if (!isFinite(n) || n <= 0) { throw new Error("GAL-02: parameter '" + name + "' must be a number above 0"); }
  return n;
}

// Step key base: label (cut to 20 code points) + queue-time timestamp + 8 hex random.
// Computed once per run; the two legs get -in and -out so they never merge.
var label = Array.from(need("batch_label")).slice(0, 20).join("");
var rand = (Math.random().toString(16) + "00000000").slice(2, 10);
var base = label + "-" + new Date().toISOString() + "-" + rand;

function stackLeg(suffix, from, to) {
  var p = {
    step_key: base + suffix,
    robot: need("robot"),
    labware_profile: need("labware_profile"),
    source_device: need(from + "_device"),
    source_deck: need(from + "_deck"),
    source_nest: need(from + "_nest"),
    destination_device: need(to + "_device"),
    destination_deck: need(to + "_deck"),
    destination_nest: need(to + "_nest")
  };
  if (text(from + "_transfer_profile") !== "") { p.source_transfer_profile = text(from + "_transfer_profile"); }
  if (text(to + "_transfer_profile") !== "") { p.destination_transfer_profile = text(to + "_transfer_profile"); }
  if (text("stack_timeout_s") !== "") { p.timeout_s = positive("stack_timeout_s"); }
  return p;
}

function fastStep() {
  var p = {};
  var decks = ["source_deck", "dest_deck"];
  for (var d = 0; d < decks.length; d++) { p[decks[d]] = wholeBetween("fast_step_" + decks[d], 1, 6); }
  var ints = ["source_plate_id", "dest_plate_id", "source_start_col", "dest_start_col", "num_rows", "num_cols"];
  for (var i = 0; i < ints.length; i++) { p[ints[i]] = wholeBetween("fast_step_" + ints[i], 1, 2147483647); }
  p.source_start_row = letters("fast_step_source_start_row");
  p.dest_start_row = letters("fast_step_dest_start_row");
  p.volume = positive("fast_step_volume");
  p.tip_reuse = oneOf("fast_step_tip_reuse", ["fresh", "reuse"]);
  if (text("fast_step_expected_tray_id") !== "") { p.expected_tray_id = whole("fast_step_expected_tray_id"); }
  return p;
}

var stackTool = need("stack_tool");
var fastTool = need("fast_tool");
function toolKey(name) { return String(name || "").toLowerCase().replace(/[^a-z0-9]/g, ""); }
if (toolKey(stackTool) === toolKey(fastTool)) { throw new Error("GAL-02: parameter 'fast_tool' must differ from 'stack_tool'"); }
if (need("source_device") === need("fast_device") && need("source_deck") === need("fast_deck") && need("source_nest") === need("fast_nest")) {
  throw new Error("GAL-02: the F.A.S.T. side (fast_device, fast_deck, fast_nest) must differ from the source side (source_device, source_deck, source_nest)");
}
var legIn = stackLeg("-in", "source", "fast");
var fastParams = fastStep();
var legOut = stackLeg("-out", "fast", "source");

galago.note("GAL-02 key base " + base);
galago.command(stackTool, "transfer", legIn);
galago.command(fastTool, "transfer", fastParams);
galago.command(stackTool, "transfer", legOut);
